1	package filestore
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"time"
8	
9		"github.com/txsaga/txsaga"
10	)
11	
12	// fileTx 是一次 Commit 的事务视图：操作对象是当前内存根的深拷贝，
13	// 回调成功且快照落盘后整根才会替换，因此回调失败或落盘失败都不留痕迹。
14	type fileTx struct {
15		business string
16		idem     string
17		binding  *txsaga.Binding
18		state    *txsaga.ExecutionState
19		created  bool
20		staged   []txsaga.Event
21	}
22	
23	func (t *fileTx) Binding() (txsaga.Binding, bool) {
24		if t.binding != nil {
25			return *t.binding, true
26		}
27		return txsaga.Binding{}, false
28	}
29	
30	func (t *fileTx) State() *txsaga.ExecutionState { return t.state }
31	
32	func (t *fileTx) Create(state *txsaga.ExecutionState) {
33		state.BusinessKey = t.business
34		state.IdempotencyKey = t.idem
35		t.state = state
36		t.created = true
37	}
38	
39	func (t *fileTx) AppendEvent(eventType string, p txsaga.EventPayload) {
40		t.staged = append(t.staged, txsaga.Event{
41			BusinessKey: t.business,
42			Type:        eventType,
43			Payload:     p,
44		})
45	}
46	
47	// cloneData 生成内存根的深拷贝：新根中的任何修改（含 fsEvent 与步骤切片）
48	// 都不会影响旧根，保证落盘失败时对外可见状态不变。
49	func cloneData(d *fsData) *fsData {
50		n := newData()
51		n.seq = d.seq
52		n.claimSeq = d.claimSeq
53		for k, b := range d.bindings {
54			bc := b
55			n.bindings[k] = bc
56		}
57		for id, st := range d.execs {
58			n.execs[id] = cloneState(st)
59		}
60		// 事件逐个复制结构（含其负载中的切片），活动索引与审计链共享新指针。
61		ptr := make(map[string]*fsEvent, len(d.events))
62		for _, old := range d.history {
63			cp := *old
64			ev := old.event
65			if ep, ok := ev.Payload.(txsaga.EventPayload); ok {
66				if ep.SucceededSteps != nil {
67					ep.SucceededSteps = append([]string(nil), ep.SucceededSteps...)
68				}
69				ev.Payload = ep
70			}
71			cp.event = ev
72			ptr[cp.event.ID] = &cp
73		}
74		n.events = ptr
75		n.pending = append([]string(nil), d.pending...)
76		for _, old := range d.history {
77			n.history = append(n.history, ptr[old.event.ID])
78		}
79		return n
80	}
81	
82	func cloneState(st *txsaga.ExecutionState) *txsaga.ExecutionState {
83		c := *st // Payload 为不透明负载，按根包内存实现的口径只做接口值复制
84		if st.Steps != nil {
85			c.Steps = append([]txsaga.StepState(nil), st.Steps...)
86		}
87		if st.SucceededOrder != nil {
88			c.SucceededOrder = append([]string(nil), st.SucceededOrder...)
89		}
90		return &c
91	}
92	
93	// mutate 在锁内克隆当前根、应用变更、原子落盘，成功后替换内存根。
94	// 回调作用于克隆根；返回错误或落盘失败时内存根保持不变。
95	func (s *FileStore) mutate(ctx context.Context, fn func(d *fsData, now time.Time) error) error {
96		s.mu.Lock()
97		defer s.mu.Unlock()
98		if err := s.ready(ctx); err != nil {
99			return err
100		}
101		next := cloneData(s.d)
102		now := s.now()
103		if err := fn(next, now); err != nil {
104			return err
105		}
106		if err := s.persist(next); err != nil {
107			// 落盘失败（含负载不可 JSON 表示）：不替换内存根，状态与事件都不变。
108			return err
109		}
110		s.d = next
111		return nil
112	}
113	
114	// LoadSnapshot 实现 txsaga.Store：读取执行身份快照与业务键定义绑定。
115	func (s *FileStore) LoadSnapshot(ctx context.Context, businessKey, idempotencyKey string) (txsaga.Snapshot, error) {
116		s.mu.Lock()
117		defer s.mu.Unlock()
118		if err := s.ready(ctx); err != nil {
119			return txsaga.Snapshot{}, err
120		}
121		snap := txsaga.Snapshot{}
122		if b, ok := s.d.bindings[businessKey]; ok {
123			snap.Binding, snap.Bound = b, true
124		}
125		if st, ok := s.d.execs[joinExecID(businessKey, idempotencyKey)]; ok {
126			snap.State = cloneState(st)
127		}
128		return snap, nil
129	}
130	
131	// Commit 实现 txsaga.Store：回调内的状态变更与事件追加在同一份快照中
132	// 原子落盘（临时文件 + fsync + 改名），要么整体可见，要么整体不可见。
133	func (s *FileStore) Commit(ctx context.Context, businessKey, idempotencyKey string, fn func(tx txsaga.Tx) error) error {
134		s.mu.Lock()
135		defer s.mu.Unlock()
136		if err := s.ready(ctx); err != nil {
137			return err
138		}
139	
140		next := cloneData(s.d)
141		t := &fileTx{business: businessKey, idem: idempotencyKey}
142		if b, ok := next.bindings[businessKey]; ok {
143			bc := b
144			t.binding = &bc
145		}
146		if st, ok := next.execs[joinExecID(businessKey, idempotencyKey)]; ok {
147			t.state = st
148		}
149	
150		if err := fn(t); err != nil {
151			return err // 回调失败：状态副本与暂存事件一并丢弃，文件不动
152		}
153	
154		now := s.now()
155		id := joinExecID(businessKey, idempotencyKey)
156		if t.state != nil {
157			if t.created {
158				if _, exists := next.execs[id]; exists {
159					return errors.New("txsaga: execution already exists")
160				}
161				t.state.CreatedAt = now
162				if _, ok := next.bindings[businessKey]; !ok {
163					next.bindings[businessKey] = txsaga.Binding{
164						SagaName:    t.state.SagaName,
165						Fingerprint: t.state.Fingerprint,
166					}
167				}
168			}
169			t.state.UpdatedAt = now
170			next.execs[id] = t.state
171		}
172	
173		for i := range t.staged {
174			ev := t.staged[i]
175			next.seq++
176			ev.ID = fmt.Sprintf("evt-%020d", next.seq)
177			ev.OccurredAt = now
178			me := &fsEvent{event: ev, idempotencyKey: idempotencyKey, alive: true}
179			next.events[ev.ID] = me
180			next.pending = append(next.pending, ev.ID)
181			next.history = append(next.history, me)
182		}
183	
184		// 先在内存中编码成功才触碰文件：负载不被 JSON 稳定支持时整体失败，
185		// 不会留下状态或事件的半次提交。
186		if err := s.persist(next); err != nil {
187			return err
188		}
189		s.d = next
190		return nil
191	}
192	
193	// ClaimPendingEvents 实现 txsaga.Store，语义与 MemoryStore 一致：
194	// 领取即锁定（直到 Ack/Nack），有效租约内的事件不被无租约领取取得。
195	func (s *FileStore) ClaimPendingEvents(ctx context.Context, max int) ([]*txsaga.Event, error) {
196		var out []*txsaga.Event
197		err := s.mutate(ctx, func(d *fsData, now time.Time) error {
198			if max <= 0 {
199				max = 16
200			}
201			out = make([]*txsaga.Event, 0, max)
202			remaining := d.pending[:0]
203			for _, eid := range d.pending {
204				me := d.events[eid]
205				if me == nil || !me.alive {
206					continue // 已 Ack，丢弃墓碑 ID
207				}
208				if me.claimID != "" && now.Before(me.claimedUntil) {
209					remaining = append(remaining, eid)
210					continue
211				}
212				if len(out) >= max {
213					remaining = append(remaining, eid)
214					continue
215				}
216				me.claimed = true
217				me.claimID = ""
218				me.claimedUntil = time.Time{}
219				me.event = me.event.WithDeliveryMeta(me.event.Deliveries()+1, now)
220				cp := me.event
221				out = append(out, &cp)
222			}
223			d.pending = remaining
224			return nil
225		})
226		if err != nil {
227			return nil, err
228		}
229		return out, nil
230	}
231	
232	// ClaimPendingEventsLeased 实现 txsaga.ClaimLeaseStore：从未领取或租约已
233	// 到期的事件可领取，每次生成新 ClaimID；事件在队列中原位保留，故到期
234	// 恢复与 Nack 都不改变追加顺序。
235	func (s *FileStore) ClaimPendingEventsLeased(ctx context.Context, ttl time.Duration, max int) ([]txsaga.ClaimedEvent, error) {
236		var out []txsaga.ClaimedEvent
237		err := s.mutate(ctx, func(d *fsData, now time.Time) error {
238			if max <= 0 {
239				max = 16
240			}
241			out = make([]txsaga.ClaimedEvent, 0, max)
242			live := d.pending[:0]
243			for _, eid := range d.pending {
244				me := d.events[eid]
245				if me == nil || !me.alive {
246					continue
247				}
248				if me.claimID != "" && now.Before(me.claimedUntil) {
249					live = append(live, eid)
250					continue
251				}
252				if len(out) >= max {
253					live = append(live, eid)
254					continue
255				}
256				d.claimSeq++
257				cid := fmt.Sprintf("claim-%020d", d.claimSeq)
258				me.claimID = cid
259				me.claimedUntil = now.Add(ttl)
260				me.event = me.event.WithDeliveryMeta(me.event.Deliveries()+1, now)
261				cp := me.event
262				out = append(out, txsaga.ClaimedEvent{
263					Event:        &cp,
264					ClaimID:      cid,
265					ClaimedUntil: me.claimedUntil,
266				})
267				live = append(live, eid)
268			}
269			d.pending = live
270			return nil
271		})
272		if err != nil {
273			return nil, err
274		}
275		return out, nil
276	}
277	
278	// AckEvent 实现 txsaga.Store：标记投递成功。活动副本退出领取与待领取队列，
279	// 审计链中的副本永久保留；事件不存在时返回错误。
280	func (s *FileStore) AckEvent(ctx context.Context, eventID string) error {
281		return s.mutate(ctx, func(d *fsData, _ time.Time) error {
282			me, ok := d.events[eventID]
283			if !ok || !me.alive {
284				return fmt.Errorf("txsaga: event %q not found", eventID)
285			}
286			me.alive = false
287			me.claimed = false
288			me.claimID = ""
289			me.claimedUntil = time.Time{}
290			return nil
291		})
292	}
293	
294	// AckLeasedEvent 实现 txsaga.ClaimLeaseStore：仅当前 claimID 可确认；
295	// 过期或他人领取返回包装了 txsaga.ErrStaleClaim 的错误且不改动事件。
296	func (s *FileStore) AckLeasedEvent(ctx context.Context, eventID, claimID string) error {
297		return s.mutate(ctx, func(d *fsData, _ time.Time) error {
298			me, ok := d.events[eventID]
299			if !ok || !me.alive {
300				return fmt.Errorf("txsaga: event %q not found", eventID)
301			}
302			if me.claimID != claimID {
303				return fmt.Errorf("txsaga: event %q claim %q is not current: %w", eventID, claimID, txsaga.ErrStaleClaim)
304			}
305			me.alive = false
306			return nil
307		})
308	}
309	
310	// NackEvent 实现 txsaga.Store：解除普通领取锁定并退回待领取队列；
311	// 未在领取中的事件幂等处理。
312	func (s *FileStore) NackEvent(ctx context.Context, eventID string) error {
313		return s.mutate(ctx, func(d *fsData, _ time.Time) error {
314			me, ok := d.events[eventID]
315			if !ok || !me.alive {
316				return fmt.Errorf("txsaga: event %q not found", eventID)
317			}
318			if !me.claimed {
319				return nil
320			}
321			me.claimed = false
322			d.pending = append(d.pending, eventID)
323			return nil
324		})
325	}
326	
327	// NackLeasedEvent 实现 txsaga.ClaimLeaseStore：仅当前 claimID 可退回，
328	// 退回后租约立即解除、事件可被领取，追加顺序不变。
329	func (s *FileStore) NackLeasedEvent(ctx context.Context, eventID, claimID string) error {
330		return s.mutate(ctx, func(d *fsData, _ time.Time) error {
331			me, ok := d.events[eventID]
332			if !ok || !me.alive {
333				return fmt.Errorf("txsaga: event %q not found", eventID)
334			}
335			if me.claimID != claimID {
336				return fmt.Errorf("txsaga: event %q claim %q is not current: %w", eventID, claimID, txsaga.ErrStaleClaim)
337			}
338			me.claimID = ""
339			me.claimedUntil = time.Time{}
340			return nil
341		})
342	}
343	
344	// PendingCount 返回当前立即可领取的活动事件数（不含有效租约内事件），
345	// 与 MemoryStore.PendingCount 的观测口径一致，便于观测与测试。
346	func (s *FileStore) PendingCount() int {
347		s.mu.Lock()
348		defer s.mu.Unlock()
349		now := s.now()
350		n := 0
351		for _, eid := range s.d.pending {
352			me := s.d.events[eid]
353			if me == nil || !me.alive {
354				continue
355			}
356			if me.claimID != "" && now.Before(me.claimedUntil) {
357				continue
358			}
359			n++
360		}
361		return n
362	}
363	
364	// TotalEvents 返回尚未 Ack 的活动事件数（含领取中、待投递），
365	// 与 MemoryStore.TotalEvents 的观测口径一致；已 Ack 事件只在历史中保留。
366	func (s *FileStore) TotalEvents() int {
367		s.mu.Lock()
368		defer s.mu.Unlock()
369		n := 0
370		for _, me := range s.d.events {
371			if me.alive {
372				n++
373			}
374		}
375		return n
376	}
