1	package filestore
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"strconv"
7		"strings"
8	
9		"github.com/txsaga/txsaga"
10	)
11	
12	// decodeSnapshot 解析并交叉校验整库快照。任何 JSON 语法错误、被截断、
13	// 未知格式/版本、引用缺失或身份不一致都视为损坏：返回包装了
14	// ErrCorruptStore 的错误，调用方不得覆盖原文件。
15	func decodeSnapshot(raw []byte) (*fsData, error) {
16		var ps persistSnapshot
17		if err := json.Unmarshal(raw, &ps); err != nil {
18			return nil, fmt.Errorf("parse snapshot: %v: %w", err, ErrCorruptStore)
19		}
20		if ps.Format != snapshotFormat {
21			return nil, fmt.Errorf("unknown snapshot format %q: %w", ps.Format, ErrCorruptStore)
22		}
23		if ps.Version != snapshotVersion {
24			return nil, fmt.Errorf("unsupported snapshot version %d: %w", ps.Version, ErrCorruptStore)
25		}
26	
27		d := newData()
28		d.seq = ps.Seq
29		d.claimSeq = ps.ClaimSeq
30	
31		// 执行记录：键必须与内部身份一致，状态体必须可解析。
32		for id, pe := range ps.Execs {
33			business, idem, ok := splitExecID(id)
34			if !ok {
35				return nil, fmt.Errorf("execution key %q malformed: %w", id, ErrCorruptStore)
36			}
37			var st txsaga.ExecutionState
38			if err := json.Unmarshal(pe.State, &st); err != nil {
39				return nil, fmt.Errorf("execution %q state: %v: %w", id, err, ErrCorruptStore)
40			}
41			if len(pe.Payload) > 0 {
42				var p any
43				if err := json.Unmarshal(pe.Payload, &p); err != nil {
44					return nil, fmt.Errorf("execution %q payload: %v: %w", id, err, ErrCorruptStore)
45				}
46				st.Payload = p
47			}
48			if st.BusinessKey != business || st.IdempotencyKey != idem {
49				return nil, fmt.Errorf("execution %q identity mismatch (got %q/%q): %w",
50					id, st.BusinessKey, st.IdempotencyKey, ErrCorruptStore)
51			}
52			if st.Steps == nil {
53				// 归一化：createExecution 总是写入非 nil 的步骤切片。
54				st.Steps = []txsaga.StepState{}
55			}
56			d.execs[id] = &st
57		}
58	
59		// 定义绑定：业务键必须与某个执行一致，名称/指纹必须匹配。
60		for business, b := range ps.Bindings {
61			if b.SagaName == "" || b.Fingerprint == "" {
62				return nil, fmt.Errorf("binding for %q is incomplete: %w", business, ErrCorruptStore)
63			}
64			matched := false
65			for id, st := range d.execs {
66				bk, _, _ := splitExecID(id)
67				if bk == business {
68					if st.SagaName != b.SagaName || st.Fingerprint != b.Fingerprint {
69						return nil, fmt.Errorf("binding for %q disagrees with execution %q: %w",
70							business, id, ErrCorruptStore)
71					}
72					matched = true
73				}
74			}
75			if !matched {
76				return nil, fmt.Errorf("binding for %q has no execution: %w", business, ErrCorruptStore)
77			}
78			d.bindings[business] = txsaga.Binding{SagaName: b.SagaName, Fingerprint: b.Fingerprint}
79		}
80	
81		// 事件：ID 唯一且编号单调（与审计链顺序一致），身份必须能找到执行，
82		// 投递元数据自洽，已 Ack 事件不得出现在待领取队列。
83		knownIDs := make(map[string]*fsEvent, len(ps.Events))
84		var lastSeqNum uint64
85		for i := range ps.Events {
86			pe := &ps.Events[i]
87			if pe.ID == "" || pe.BusinessKey == "" || pe.Type == "" || pe.IdempotencyKey == "" {
88				return nil, fmt.Errorf("event at %d missing identity fields: %w", i, ErrCorruptStore)
89			}
90			if pe.OccurredAt.IsZero() {
91				return nil, fmt.Errorf("event %q has zero occurrence time: %w", pe.ID, ErrCorruptStore)
92			}
93			num, err := parseEventID(pe.ID)
94			if err != nil {
95				return nil, fmt.Errorf("%v: %w", err, ErrCorruptStore)
96			}
97			if i > 0 && num <= lastSeqNum {
98				return nil, fmt.Errorf("event %q out of append order: %w", pe.ID, ErrCorruptStore)
99			}
100			lastSeqNum = num
101			if _, dup := knownIDs[pe.ID]; dup {
102				return nil, fmt.Errorf("duplicated event id %q: %w", pe.ID, ErrCorruptStore)
103			}
104			// 事件允许引用尚不存在的执行（MemoryStore 同样允许只追加事件）：
105			// 历史查询按身份过滤，执行不存在时查询侧返回 ErrExecutionNotFound。
106			var ep txsaga.EventPayload
107			if err := json.Unmarshal(pe.Payload, &ep); err != nil {
108				return nil, fmt.Errorf("event %q payload: %v: %w", pe.ID, err, ErrCorruptStore)
109			}
110			if pe.Deliveries < 0 {
111				return nil, fmt.Errorf("event %q has negative deliveries: %w", pe.ID, ErrCorruptStore)
112			}
113			if (pe.ClaimID == "") != pe.ClaimedUntil.IsZero() {
114				return nil, fmt.Errorf("event %q lease fields inconsistent: %w", pe.ID, ErrCorruptStore)
115			}
116			if pe.Claimed && pe.ClaimID != "" {
117				// 普通领取与租约领取互斥（内存实现接管到期租约会清除 ClaimID）。
118				return nil, fmt.Errorf("event %q held by both claim kinds: %w", pe.ID, ErrCorruptStore)
119			}
120			ev := txsaga.Event{
121				ID:          pe.ID,
122				BusinessKey: pe.BusinessKey,
123				Type:        pe.Type,
124				OccurredAt:  pe.OccurredAt,
125				Payload:     ep,
126			}
127			ev = ev.WithDeliveryMeta(pe.Deliveries, pe.LastAttemptAt)
128			me := &fsEvent{
129				event:          ev,
130				idempotencyKey: pe.IdempotencyKey,
131				claimed:        pe.Claimed,
132				claimID:        pe.ClaimID,
133				claimedUntil:   pe.ClaimedUntil,
134				alive:          !pe.Acked,
135			}
136			knownIDs[pe.ID] = me
137			d.history = append(d.history, me)
138		}
139		if ps.Seq < lastSeqNum {
140			return nil, fmt.Errorf("snapshot seq %d behind last event %d: %w",
141				ps.Seq, lastSeqNum, ErrCorruptStore)
142		}
143	
144		// 待领取队列：引用必须存在、未 Ack、不重复。
145		seen := make(map[string]struct{}, len(ps.Pending))
146		for _, id := range ps.Pending {
147			me, ok := knownIDs[id]
148			if !ok {
149				return nil, fmt.Errorf("pending event %q missing from event chain: %w", id, ErrCorruptStore)
150			}
151			if !me.alive {
152				return nil, fmt.Errorf("acked event %q still pending: %w", id, ErrCorruptStore)
153			}
154			if _, dup := seen[id]; dup {
155				return nil, fmt.Errorf("pending event %q duplicated: %w", id, ErrCorruptStore)
156			}
157			seen[id] = struct{}{}
158			d.pending = append(d.pending, id)
159		}
160		d.events = knownIDs
161		return d, nil
162	}
163	
164	// joinExecID / splitExecID 与根包内部 execID 同构（business+'\x00'+idem），
165	// 快照 map 直接以该串为键，避免再引入一套键格式。
166	func joinExecID(businessKey, idempotencyKey string) string {
167		return businessKey + "\x00" + idempotencyKey
168	}
169	
170	func splitExecID(id string) (business, idem string, ok bool) {
171		idx := strings.IndexByte(id, 0)
172		if idx <= 0 || idx == len(id)-1 {
173			return "", "", false
174		}
175		return id[:idx], id[idx+1:], true
176	}
177	
178	// parseEventID 解析根包分配的 evt-%020d 事件编号，用于顺序与序号校验。
179	func parseEventID(id string) (uint64, error) {
180		const prefix = "evt-"
181		if !strings.HasPrefix(id, prefix) || len(id) != len(prefix)+20 {
182			return 0, fmt.Errorf("event %q has unexpected id shape", id)
183		}
184		n, err := strconv.ParseUint(id[len(prefix):], 10, 64)
185		if err != nil || n == 0 {
186			return 0, fmt.Errorf("event %q has non-numeric or zero sequence", id)
187		}
188		return n, nil
189	}
