func (r *Relay) deliverOnceBounded(ctx context.Context, ds DeadLetterStore) (RelayResult, error) {
    events, dead, err := ds.ClaimPendingEventsBounded(ctx, r.maxDeliveries, r.batch)
    if err != nil {
        return RelayResult{}, err
    }
    res := RelayResult{Claimed: len(events), DeadLettered: dead}
    for _, ev := range events {
        if err := ctx.Err(); err != nil {
            _ = r.store.NackEvent(ctx, ev.ID)
            res.Failed++
            continue
        }
        if pubErr := r.publisher.Publish(ctx, *ev); pubErr != nil {
            dl, nackErr := ds.NackEventBounded(ctx, ev.ID, pubErr.Error(), r.maxDeliveries)
            if nackErr != nil {
                return res, nackErr
            }
            if dl {
                res.DeadLettered++
            } else {
                res.Failed++
            }
            continue
        }
        if err := r.store.AckEvent(ctx, ev.ID); err != nil {
            return res, err
        }
        res.Delivered++
    }
    return res, nil
}
