// removePending 从待领取队列移除事件 ID（死信隔离时使用）。
func (s *MemoryStore) removePending(eventID string) {
	kept := s.pending[:0]
	for _, id := range s.pending {
		if id != eventID {
			kept = append(kept, id)
		}
	}
	s.pending = kept
}
