	}
	if me.dead {
		return true, nil // 已被隔离：幂等
	}
	if !me.claimed {
		return false, nil // 幂等退回：未在领取中的事件无需处理
	}
	me.lastError = reason
	if roundExhaustedLocked(me, maxDeliveries) {
		s.deadLetterLocked(me, s.now())
