}

// NackLeasedEventBounded 实现 DeadLetterLeaseStore：仅当前 claimID 可
// 退回；达到上限时在同一操作中原子转为死信。
func (s *MemoryStore) NackLeasedEventBounded(_ context.Context, eventID, claimID, reason string, maxDeliveries int) (bool, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
