func (s *MemoryStore) RequeueDeadLetterEvent(ctx context.Context, eventID string) error {
	if err := ctx.Err(); err != nil {
		return err // ctx 取消：不改变事件
	}
	s.mu.Lock()
	defer s.mu.Unlock()
