			dead++
			continue
		}
		if len(out) >= max {
			remaining = append(remaining, id)
			continue
		}
		me.claimed = true
		me.claimID = ""
		me.claimedUntil = time.Time{}
		me.event.deliveries++
		me.event.lastAttemptAt = now
		cp := me.event
		out = append(out, &cp)
	}
	s.pending = remaining
