			if me == nil || !me.alive {
				continue
			}
			if me.claimID != "" && now.Before(me.claimedUntil) {
				live = append(live, eid)
				continue
			}
			if len(out) >= max {
				live = append(live, eid)
				continue
			}
			d.claimSeq++
			cid := fmt.Sprintf("claim-%020d", d.claimSeq)
			me.claimID = cid
