package filestore

import (
	"context"

	"github.com/txsaga/txsaga"
)

const defaultEventHistoryLimit = 100

// ListEvents 实现 txsaga.EventHistoryStore：按追加顺序返回一次执行的一页
// 事件，语义与 MemoryStore.ListEvents 完全一致。
//
//   - 执行不存在（含仅有事件、没有执行记录）或 Saga 名称不符：
